<script setup>
import {computed} from "vue";import AdminLayout from "../components/admin/AdminLayout.vue";import DataTable from "../components/DataTable.vue";import {useServerTable} from "../services/serverTable";import {t} from "../services/i18n";const{items,loading,pagination,load}=useServerTable({endpoint:"/api/v1/admin/cashier_shifts",collectionKey:"cashier_shifts"});const columns=computed(()=>[{key:"shift_number",label:t("shift.number")},{key:"user_email",label:t("shift.cashier"),sortable:false},{key:"opened_at",label:t("shift.opened_at")},{key:"closed_at",label:t("shift.closed_at")},{key:"opening_cash",label:t("shift.opening_cash")},{key:"cash_difference",label:t("shift.difference")},{key:"status",label:t("common.status")}]);const money=v=>new Intl.NumberFormat("id-ID").format(v||0);</script>
<template><AdminLayout><div class="mx-auto max-w-[1536px]"><h1 class="mb-6 text-2xl font-semibold dark:text-white">{{t('shift.history_title')}}</h1><DataTable :items="items" :columns="columns" :loading="loading" server-mode :total="pagination.total" @request="load"><template #cell-opened_at="{item}">{{new Date(item.opened_at).toLocaleString()}}</template><template #cell-closed_at="{item}">{{item.closed_at?new Date(item.closed_at).toLocaleString():'—'}}</template><template #cell-opening_cash="{item}">Rp{{money(item.opening_cash)}}</template><template #cell-cash_difference="{item}">{{item.cash_difference==null?'—':`Rp${money(item.cash_difference)}`}}</template></DataTable></div></AdminLayout></template>
